-- PKG_DMF0072 — META 전환 확인 (조회 전용)
SET PAGESIZE 200 LINESIZE 300

-- DMF0072_GET_DATA_TYPE_LIST → PKG_DMF0072.P_DMF0072_GET_DATA_TYPE_LIST
SELECT API_ID, API_URL, CASE WHEN API_URL = 'PKG_DMF0072.P_DMF0072_GET_DATA_TYPE_LIST' THEN 'OK' ELSE 'NG' END CHK FROM SCM_MGR.SCM_ADM_API_M WHERE API_ID IN ('P_DMF0072_DATATYPE_GET');
SELECT 'PKG_DMF0072.P_DMF0072_GET_DATA_TYPE_LIST' PROC_NM,
       (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM = 'PKG_DMF0072.P_DMF0072_GET_DATA_TYPE_LIST') NEW_ROWS,
       (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_PROC_M WHERE UPPER(PROC_NM) = 'DMF0072_GET_DATA_TYPE_LIST') STANDALONE_ROWS,
       (SELECT COUNT(*) FROM USER_ARGUMENTS WHERE PACKAGE_NAME = 'PKG_DMF0072' AND OBJECT_NAME = 'P_DMF0072_GET_DATA_TYPE_LIST' AND DATA_LEVEL = 0) MEMBER_ARGS,
       (SELECT LISTAGG(COL_TP_CD, ',') WITHIN GROUP (ORDER BY SORT_ORD) FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM = 'PKG_DMF0072.P_DMF0072_GET_DATA_TYPE_LIST') PROC_M_INOUT,
       (SELECT LISTAGG(REPLACE(IN_OUT, 'IN/OUT', 'INOUT'), ',') WITHIN GROUP (ORDER BY POSITION) FROM USER_ARGUMENTS WHERE PACKAGE_NAME = 'PKG_DMF0072' AND OBJECT_NAME = 'P_DMF0072_GET_DATA_TYPE_LIST' AND DATA_LEVEL = 0) MEMBER_INOUT
  FROM DUAL;

